-- mvtk/tiled/spawners/traversal.lua
-- Generated by splitting mvtk.tiled.object_spawner handlers by domain.

local OP = require "mvtk.tiled.object_props"

return function(H)
    local handlers = {}

    local M = H.M
    local Util = H.Util
    local TriggerPayloads = H.TriggerPayloads
    local CollectibleManager = H.CollectibleManager
    local EnemyManager = H.EnemyManager
    local TileSnap = H.TileSnap
    local get_gate_manager = H.get_gate_manager
    local gate_types = H.gate_types
    local get_boss_arena = H.get_boss_arena
    local get_tile_settings = H.get_tile_settings
    local get_room_world_offset = H.get_room_world_offset
    local to_bool = H.to_bool
    local resolve_rect_size_pixels = H.resolve_rect_size_pixels
    local rect_scale_from_size = H.rect_scale_from_size
    local resolve_breakable_swap_extent = H.resolve_breakable_swap_extent
    local parse_color_string = H.parse_color_string
    local non_empty_string = H.non_empty_string
    local resolve_boss_preset = H.resolve_boss_preset
    local resolve_boss_display_name = H.resolve_boss_display_name
    local get_props = H.get_props
    local make_id = H.make_id
    local world_point = H.world_point
    local world_rect = H.world_rect
    local spawn_factory = H.spawn_factory
    local spawn_collection = H.spawn_collection
    local post_collectible_tiled_overrides = H.post_collectible_tiled_overrides
    local apply_scale = H.apply_scale
    local make_scale = H.make_scale
    local send_tiled_props = H.send_tiled_props
    local log_spawn = H.log_spawn
    local log_register = H.log_register
    local get_type_prop = H.get_type_prop
    local record_error = H.record_error
    local normalize_gate_type_name = H.normalize_gate_type_name
    local normalize_gate_item_name = H.normalize_gate_item_name
    local parse_drops_string = H.parse_drops_string
    local resolve_chest_loot_table = H.resolve_chest_loot_table
    local resolve_difficulty_scaling = H.resolve_difficulty_scaling
    local print = H.print
    local polyline_registry = H.polyline_registry

    local function optional_id(value)
        local id = non_empty_string(value)
        return id == "none" and nil or id
    end

function handlers.gate(object, room_id)
    local props = get_props(object)
    local gate_type = normalize_gate_type_name(props.gate_type or object.name or "ability_requirement")
    local gate_id = make_id(props, "gate_id", "gate", object, room_id)

    if gate_type and gate_types and not gate_types[gate_type] then
        record_error(string.format("Gate '%s' uses unknown gate_type '%s' (define in developer/config/gate_types.lua)", gate_id, tostring(gate_type)))
        return nil
    end
    
    -- Get room world offset and apply it to the position.
    -- Rectangle objects are authored as bottom-left in Defold space after conversion.
    local raw_width = tonumber(object.width) or 0
    local raw_height = tonumber(object.height) or 0
    local is_point = object.point or object.shape == "point" or (raw_width <= 0 and raw_height <= 0)

    local tile = get_tile_settings()
    local tile_w = tonumber(tile.width) or 128
    local tile_h = tonumber(tile.height) or tile_w
    local width, height = resolve_rect_size_pixels(raw_width, raw_height, tile_w, tile_h)

    local world_x, world_y, pos
    if is_point then
        world_x, world_y, pos = world_point(object, room_id)
    else
        world_x, world_y, pos, width, height = world_rect(object, room_id, width, height)
    end

    local required_ability = optional_id(props.required_ability) or ""
    local required_action = optional_id(props.required_action) or ""
    if required_action == "" then
        required_action = required_ability
    end
    local required_item = optional_id(props.required_item) or ""
    if required_item == "" then
        required_item = optional_id(props.required_key) or ""
    end
    required_item = normalize_gate_item_name(required_item)
    
    -- Register gate config with GateManager so requirements are honored
    local gm = get_gate_manager()
    if gm and gm.spawn_gate then
        local gate_config = {
            id = gate_id,
            gate_type = gate_type,
            room_id = room_id,
            position = { x = world_x, y = world_y },
            size = { w = width, h = height },
        }
        if required_ability ~= "" then
            gate_config.required_ability = required_ability
        end
        if required_action ~= "" then
            gate_config.required_action = required_action
        end
        if required_item ~= "" then
            gate_config.required_item = required_item
        end
        if props.open_message and props.open_message ~= "" then
            gate_config.interaction = gate_config.interaction or {}
            gate_config.interaction.open_message = props.open_message
            gate_config.interaction.proximity_hint = props.open_message
            gate_config.open_message = props.open_message
        end
        if props.starts_open ~= nil then
            gate_config.starts_open = to_bool(props.starts_open, false)
        end
        if props.stays_open ~= nil then
            gate_config.stays_open = to_bool(props.stays_open, true)
        end
        if props.persist_unlock ~= nil then
            gate_config.persist_unlock = to_bool(props.persist_unlock, true)
        end
        pcall(gm.spawn_gate, gate_config)
        if gate_config.starts_open then
            pcall(gm.unlock_gate, gate_id, "tiled_start", {
                temporary = not gate_config.stays_open,
                persist_unlock = gate_config.persist_unlock,
            })
        end
    end

    -- Spawn the gate prefab with authored text properties
    local scale = make_scale(width, height, 64, 64, 128, 128)
    local instance = spawn_factory("gate_factory", pos, {
        gate_id = gate_id,
        gate_type = gate_type,
    }, scale, "gate")

    if not instance then
        return nil
    end

    log_spawn("gate", gate_id, world_x, world_y,
        string.format("(type: %s) size=(%.0f,%.0f) shape=%s", gate_type, width, height, is_point and "point" or "rect"))

    return {
        spawn_id = gate_id,
        instance_url = instance,
    }
end

--- Handle breakable wall object
-- A destructible wall that blocks player passage until destroyed.
-- When broken, the wall is permanently removed, opening access to new areas.
-- Tiled properties:
--   wall_type: string (e.g. "cracked", "bomb_only", "subtle") - visual variant
--   required_ability: string (e.g. "bomb", "charge_attack") - ability needed to damage
--   health: number (hits to destroy, default 3)
--   reveals_secret: string (secret area ID to reveal on minimap when broken)
--   drop_collectible: string (collectible type to spawn on break)
--   swap_tiles_on_break: bool (replace wall-layer tiles on destroy, default true)
--   wall_layer: string (tile layer to clear/replace, default "solid")
--   broken_wall_layer: string (tile layer containing replacement tiles, default "broken_wall")
--   swap_width/swap_height: number (world-space tile replacement area)

function handlers.breakable_wall(object, room_id)
    local props = get_props(object)
    local wall_type = props.wall_type or "cracked"
    local wall_id = make_id(props, "wall_id", "wall", object, room_id)
    local tile = get_tile_settings()
    local fallback_w = tonumber(tile and tile.width) or 64
    local fallback_h = tonumber(tile and tile.height) or fallback_w
    if fallback_w <= 0 then fallback_w = 64 end
    if fallback_h <= 0 then fallback_h = fallback_w end

    local snapped_object = object
    local width
    local height
    if TileSnap and TileSnap.snap_rect_bounds_to_tile then
        local snapped_x, snapped_y, snapped_w, snapped_h = TileSnap.snap_rect_bounds_to_tile(
            object.x,
            object.y,
            object.width,
            object.height,
            fallback_w,
            fallback_h,
            fallback_w,
            fallback_h
        )
        snapped_object = {
            x = snapped_x,
            y = snapped_y,
            width = snapped_w,
            height = snapped_h,
        }
        width = snapped_w
        height = snapped_h
    else
        -- When tile snapping is unavailable, still default missing object
        -- size to one configured tile instead of a hard-coded 64x64.
        local _, _, resolved_w, resolved_h = rect_scale_from_size(
            object.width,
            object.height,
            32,
            32,
            fallback_w,
            fallback_h
        )
        width = resolved_w
        height = resolved_h
        if width == 0 then width = fallback_w end
        if height == 0 then height = fallback_h end
    end

    local swap_tiles_on_break = to_bool(props.swap_tiles_on_break, to_bool(props.swap_tiles, true))
    local wall_layer_name = non_empty_string(props.wall_layer) or "wall"
    local broken_wall_layer_name = non_empty_string(props.broken_wall_layer) or "broken_wall"
    local swap_width = resolve_breakable_swap_extent(OP.get(props, "swap_width"), width, fallback_w)
    local swap_height = resolve_breakable_swap_extent(OP.get(props, "swap_height"), height, fallback_h)

    -- Center position for Defold GO
    local world_x, world_y, pos = world_rect(snapped_object, room_id, width, height)

    -- Pass scale at creation time so physics shapes scale correctly
    local spawn_scale = make_scale(width, height, 32, 32, fallback_w, fallback_h)
    local instance = spawn_factory("breakable_wall_factory", pos, {
        wall_id = wall_id,
        wall_type = wall_type,
        required_ability = optional_id(props.required_ability) or "",
        health = props.health or 3,
        room_id = room_id,
        reveals_secret = props.reveals_secret or "",
        drop_collectible = optional_id(props.drop_collectible) or "",
        swap_tiles_on_break = swap_tiles_on_break,
        wall_layer = wall_layer_name,
        broken_wall_layer = broken_wall_layer_name,
        swap_width = swap_width,
        swap_height = swap_height,
        particle_effect_name = props.particle_effect_name or "hit_impact",
        sound_break = props.sound_break or "wall_break",
    }, spawn_scale, "breakable wall")

    if not instance then
        return nil
    end

    log_spawn("breakable wall", wall_id, world_x, world_y,
        string.format("(type: %s, size: %.0fx%.0f)", wall_type, width, height))
    return instance
end

--- Handle hazard zone object
-- Tiled properties:
--   hazard_id: string (optional target id for TriggerBus wiring)
--   hazard_type: string (e.g. "spikes", "lava", "acid", "electricity", "poison")
--   damage: number (damage per tick)
--   damage_interval: number (seconds between ticks)
--   knockback_force: number
--   required_resistance: string (ability that grants immunity)
--   instant_kill: bool (one-hit kill)
--   enabled: bool (can be toggled by triggers/arena phases)
--   retractable: bool (spikes that retract)
--   retract_time: number (time spikes stay retracted)
--   extend_time: number (time spikes stay extended)
--   start_retracted: bool (start in retracted state)
--   arena_id: string (link to arena for phase control)
--   active_phases: string (comma-separated phase numbers when active)
--   pattern: string (movement/activation pattern)

local function spawn_joint_platform(object, room_id)
    local props = get_props(object)
    local platform_id = make_id(props, "platform_id", "rail", object, room_id)
    local scale_x, scale_y, width, height = rect_scale_from_size(object.width, object.height, 64, 16, 128, 32)
    local _, _, pos = world_rect(object, room_id, width, height)
    local platform_type = tostring(props.platform_type or ""):lower()
    local distance = tonumber(props.distance) or 0
    local path_dx = tonumber(props.path_dx) or 0
    local path_dy = tonumber(props.path_dy) or 0
    if path_dx == 0 and path_dy == 0 then
        if platform_type == "horizontal" then
            path_dx = distance ~= 0 and distance or 200
        else
            path_dy = distance ~= 0 and distance or 160
        end
    end

    local instance = spawn_factory("joint_platform_factory", pos, {
        path_dx = path_dx,
        path_dy = path_dy,
        duration = tonumber(props.duration) or 2,
        wait = tonumber(OP.get(props, "wait")) or 0,
        enabled = to_bool(props.enabled, true),
        loop_mode = OP.get(props, "loop_mode", "pingpong"),
        room_id = room_id,
    }, vmath.vector3(scale_x, scale_y, 1), "rail platform")

    if not instance then
        return nil
    end

    log_spawn("rail platform", platform_id, pos.x, pos.y,
        string.format("(size: %.0fx%.0f)", width, height))
    return instance
end

function handlers.joint_platform(object, room_id)
    return spawn_joint_platform(object, room_id)
end

function handlers.rail_elevator(object, room_id)
    return spawn_joint_platform(object, room_id)
end

function handlers.platform(object, room_id)
    print(string.format("[OBJECT_SPAWNER] SKIPPING platform creation for '%s' - platforms created by editor script", object.name or object.id))
    return nil
end

--- Handle boss spawn object
-- Tiled properties:
--   boss_preset: string (optional preset/default from boss_types.lua)
--   phase_config: string (optional override for phase behavior)
--   intro_cutscene: string (cutscene to play before fight)
--   arena_lock: bool (lock room during fight)

function handlers.fast_travel(object, room_id)
    local props = get_props(object)
    local station_id = make_id(props, "station_id", "travel", object, room_id)
    local station_name = non_empty_string(props.station_name)
        or non_empty_string(props.display_name)
        or non_empty_string(object.name)
        or "Travel Point"
    local station_description = non_empty_string(props.station_description)
        or non_empty_string(props.description)
        or ""
    local _, _, pos = world_point(object, room_id)

    -- auto_unlock (template) is the inverse of requires_unlock (code)
    local requires_unlock = props.requires_unlock
    if requires_unlock == nil then
        local auto_unlock = props.auto_unlock
        if auto_unlock ~= nil then
            requires_unlock = not to_bool(auto_unlock, false)
        else
            requires_unlock = true
        end
    end

    msg.post("main:/main_go#script", hash("register_fast_travel"), {
        id = station_id,
        station_name = station_name,
        station_description = station_description,
        position = pos,
        room_id = room_id,
        requires_unlock = requires_unlock,
        unlock_cost = props.unlock_cost or 0,
        icon = props.icon or "fast_travel",
        show_on_map = to_bool(props.show_on_map, true),
        facing = props.facing or 1,
        properties = props,
    })

    log_register("fast travel", station_id, pos.x, pos.y)
    return station_id
end

