--- Handle teleporter object
-- Tiled properties:
--   teleporter_id: string
--   pair_id: string
--   target_id: string (optional)
--   requires_flag: string (optional)
--   hide_when_locked: bool (optional)
--   active_effect_id: string (optional, blank disables the idle effect)
--   unlock_effect_id: string (optional one-shot when the teleporter unlocks)
--   require_interact: bool
--   cooldown: number
--   transition_time: number
--   preserve_velocity: bool
--   facing: int
--   label: string
--   fade_out: number (seconds for fade-to-black on cross-room teleport)
--   fade_in: number (seconds for fade-from-black on cross-room teleport)
--   one_way: bool (if true, this teleporter is receive-only and won't send)

function handlers.teleporter(object, room_id)
    local props = get_props(object)
    local teleporter_id = make_id(props, "teleporter_id", "teleporter", object, room_id)

    local tile = get_tile_settings()
    local tile_w = tonumber(tile.width) or 128
    local tile_h = tonumber(tile.height) or tile_w
    if tile_w <= 0 then tile_w = 128 end
    if tile_h <= 0 then tile_h = tile_w end

    local width, height = resolve_rect_size_pixels(object.width, object.height, tile_w, tile_h)
    local world_x, world_y, pos = world_rect(object, room_id, width, height)
    local spawn_scale = make_scale(width, height, 64, 64, 128, 128)

    local instance = spawn_factory("teleporter_factory", pos, {
        teleporter_id = teleporter_id,
        pair_id = props.pair_id or "",
        target_id = props.target_id or "",
        room_id = room_id,
        requires_flag = props.requires_flag or "",
        hide_when_locked = to_bool(props.hide_when_locked, false),
        active_effect_id = props.active_effect_id or "collectible_sparkle",
        unlock_effect_id = optional_id(props.unlock_effect_id) or "",
        require_interact = to_bool(props.require_interact, false),
        cooldown = props.cooldown or 0.5,
        transition_time = props.transition_time or 0.0,
        preserve_velocity = to_bool(props.preserve_velocity, false),
        facing = props.facing or 0,
        label = props.label or "",
        fade_out = props.fade_out or 0.5,
        fade_in = props.fade_in or 0.5,
        one_way = to_bool(props.one_way, false),
        interact_range = math.max(width, height) * 0.5 + 16,
    }, spawn_scale, "teleporter")

    if not instance then
        return nil
    end

    log_spawn("teleporter", teleporter_id, world_x, world_y,
        string.format("size=(%.0f, %.0f)", width, height))
    return instance
end

--- Handle grapple point object
-- Tiled properties:
--   grapple_id: string (unique identifier for this grapple point)
--   require_ability: string (ability needed to use, e.g. "grapple")
--   one_way: bool (can only grapple TO this point, not launch from it)
--   pull_speed: number (override grapple pull speed, 0 = use default)
--   launch_speed: number (speed boost when releasing from this point)
--   sound_id: string (sound to play when latching)

function handlers.grapple_point(object, room_id)
    local props = get_props(object)
    local width = tonumber(object.width) or 0
    local height = tonumber(object.height) or 0
    local world_x, world_y, pos
    if width > 0 or height > 0 then
        world_x, world_y, pos = world_rect(object, room_id, 32, 32)
    else
        world_x, world_y, pos = world_point(object, room_id)
    end

    local instance = spawn_factory("grapple_point_factory", pos, {
        grapple_id = hash(props.grapple_id or string.format("grapple_%s_%d", tostring(room_id), object.id)),
        require_ability = hash(props.require_ability or "grapple"),
        one_way = to_bool(props.one_way, false),
        pull_speed = tonumber(props.pull_speed) or 0,
        launch_speed = tonumber(props.launch_speed) or 0,
        sound_id = hash(props.sound_id or ""),
    }, 1, "grapple point")
    if not instance then
        return nil
    end

    if width > 0 and height > 0 then
        apply_scale(instance, width, height, 24, 24, 48, 48)
    end

    log_spawn("grapple point", props.grapple_id or "auto", world_x, world_y)
    return instance
end

