function handlers.pushable_block(object, room_id)
    local props = get_props(object)
    local block_id = make_id(props, "block_id", "block", object, room_id)

    local tile = get_tile_settings()
    local tile_w = tonumber(tile.width) or 128
    local tile_h = tonumber(tile.height) or tile_w
    if tile_w <= 0 then tile_w = 128 end
    if tile_h <= 0 then tile_h = tile_w end

    local resolved_w, resolved_h = resolve_rect_size_pixels(object.width, object.height, tile_w, tile_h)
    local _, _, pos = world_rect(object, room_id, resolved_w, resolved_h)

    local instance = spawn_factory("pushable_block_factory", pos, {
        block_id = block_id,
        room_id = room_id,
        reset_on_room_load = to_bool(props.reset_on_room_load, false),
        move_embedded_tiles = to_bool(props.move_embedded_tiles, true),
        capture_width = resolved_w,
        capture_height = resolved_h,
        debug_tile_chunk = to_bool(props.debug_tile_chunk, false),
    }, 1, "pushable block")

    if not instance then return nil end

    apply_scale(instance, resolved_w, resolved_h, 64, 64, 128, 128)

    log_spawn("pushable block", block_id, pos.x, pos.y)
    return instance
end

