--- Handle one-way platform object

function handlers.one_way_platform(object, room_id)
    local props = get_props(object)
    local direction = tostring(props.direction or "down"):lower()
    if direction ~= "up" then
        direction = "down"
    end

    local _, _, pos = world_rect(object, room_id, 128, 16)

    local instance = spawn_factory("one_way_platform_factory", pos, {
        direction = direction,
    }, 1, "one-way platform")

    if not instance then return nil end

    apply_scale(instance, object.width, object.height, 128, 16, 256, 32)

    log_spawn("one-way platform", direction, pos.x, pos.y)
    return instance
end

--- Handle background interactable object
-- Tiled properties:
--   interact_id: string
--   label: string
--   range: number
--   message_id: string
--   target_id: string
--   enable_interaction: bool
--   trigger_once: bool
--   set_flag/requires_flag: string
--   break_on_interact: bool (default true)
--   break_on_attack: bool (default true)
--   break_health: number (default 1)
--   required_attack_type: string
--   idle_animation: string
--   break_animation: string
--   broken_animation: string
--   break_disable_interaction: bool (default true)
--   hide_on_break/delete_on_break: bool
--   break_sound: string
--   break_fx_id: string (fx_manager effect id)
--   drop_collectible: string
--   drop_count: number
--   drop_spread: number
--   drop_persistent: bool

function handlers.moving_platform(object, room_id)
    local props = get_props(object)
    local platform_id = non_empty_string(props.platform_id)
        or string.format("platform_%s_%d", tostring(room_id), tonumber(object.id) or 0)
    local _, _, pos = world_point(object, room_id)

    -- Try to resolve path from polyline registry
    local path_points = nil
    if props.path_name then
        local room_polylines = polyline_registry[room_id]
        if room_polylines and room_polylines[props.path_name] then
            path_points = room_polylines[props.path_name]
        end
    end

    local instance = spawn_factory("moving_platform_factory", pos, {
        platform_id = platform_id,
        speed = props.speed or 100,
        wait_time = props.wait_time or 1.0,
        mode = props.mode or "pingpong",
        start_delay = props.start_delay or 0,
        trigger_id = props.trigger_id or "",
        player_parent = to_bool(props.player_parent, true),
    }, 1, "moving platform")

    if not instance then return nil end

    -- Send path data if available
    if path_points then
        pcall(msg.post, instance, hash("set_path"), { points = path_points })
    end

    apply_scale(instance, object.width, object.height, 64, 16, 128, 32)

    send_tiled_props(instance, props)

    log_spawn("moving platform", platform_id, pos.x, pos.y)
    return instance
end

-- Cross-room elevators are compiled as a global route by Create Rooms and
-- represented by baked editor markers. These handlers intentionally do not
-- create a second runtime object; they exist so registry/type parity remains
-- complete if a loader inspects the exported objects before applying its
-- generated skip flags.
function handlers.elevator(object, room_id)
    local props = get_props(object)
    log_register("elevator controller", props.elevator_id or object.name or object.id, room_id)
    return nil
end

function handlers.elevator_node(object, room_id)
    local props = get_props(object)
    log_register("elevator node", props.node_id or object.name or object.id, room_id)
    return nil
end

--- Handle health station object (healing fountain, etc.)
-- Tiled properties:
--   station_id: string (unique identifier)
--   label: string (interaction label override)
--   range: number (interaction range in pixels)
--   heal_amount: number (health to restore, 0 = full heal)
--   heal_percent: number (0.0-1.0, percentage of max health)
--   uses: number (how many times can be used, 0 = unlimited)
--   recharge_time: number (seconds before can be used again, 0 = one-time)
--   cost_currency: number (currency cost to use)
--   require_interact: bool (true = button prompt, false = auto trigger)
--   requires_flag: string (flag that must be set to use)
--   sound_id: string (sound to play when used)
--   particle_id: string (particle effect when used)

function handlers.wall_jump_surface(object, room_id)
    local props = get_props(object)
    local surface_id = props.surface_id or string.format("wall_%s_%d", tostring(room_id), object.id)
    local _, _, pos = world_rect(object, room_id, 32, 128)

    local facing = props.facing
    if facing == nil then facing = props.direction end
    if type(facing) == "string" then
        local dir = facing:lower()
        if dir == "left" then
            facing = -1
        elseif dir == "right" then
            facing = 1
        else
            facing = 0
        end
    end
    if facing == nil then facing = 1 end

    local require_ability = OP.get(props, "require_ability", "")

    local instance = spawn_factory("wall_jump_surface_factory", pos, {
        surface_id = surface_id,
        allow_slide = to_bool(props.allow_slide, true),
        allow_jump = to_bool(props.allow_jump, true),
        allow_climb = to_bool(props.allow_climb, false),
        slide_speed = tonumber(props.slide_speed) or 0.3,
        jump_force_x = tonumber(props.jump_force_x) or 400,
        jump_force_y = tonumber(props.jump_force_y) or 500,
        facing = facing,
        require_ability = require_ability,
        surface_type = props.surface_type or "stone",
    }, 1, "wall jump surface")

    if not instance then return nil end

    apply_scale(instance, object.width, object.height, 16, 64, 32, 128)

    send_tiled_props(instance, props)

    log_spawn("wall jump surface", surface_id, pos.x, pos.y)
    return instance
end

--- Handle spike hazard (classic platformer spikes)
-- Tiled properties:
--   damage: number (damage dealt on contact)
--   knockback: number (knockback force in pixels)
--   direction: string ("up", "down", "left", "right") - spike orientation
--   retractable: bool (if true, spikes can retract)
--   retract_time: number (seconds spikes stay retracted)
--   extend_time: number (seconds spikes stay extended)
--   start_retracted: bool (if true, starts in retracted state)

    return handlers
end
